     9	    public async Task<IReadOnlyList<ContextArtifact>> LoadAsync(
    10	        string? configuredRoot,
    11	        CancellationToken cancellationToken)
    12	    {
    13	        var root = ResolveRoot(configuredRoot);
    14	        var manifestPath = Path.Combine(root, "manifest.json");
    15	        if (!File.Exists(manifestPath))
    16	        {
    17	            throw new FileNotFoundException("The cognitive manifest was not found.", manifestPath);
    18	        }
    19	
    20	        await using var stream = File.OpenRead(manifestPath);
    21	        var manifest = await JsonSerializer.DeserializeAsync<CognitiveManifest>(
    22	            stream,
    23	            new JsonSerializerOptions { PropertyNameCaseInsensitive = true },
    24	            cancellationToken).ConfigureAwait(false)
    25	            ?? throw new InvalidDataException("The cognitive manifest is empty.");
    26	
    27	        var artifacts = new List<ContextArtifact>();
    28	
    29	        foreach (var entry in manifest.Files.OrderBy(item => item.Path, StringComparer.Ordinal))
    30	        {
    31	            cancellationToken.ThrowIfCancellationRequested();
    32	            if (!entry.Path.EndsWith(".md", StringComparison.OrdinalIgnoreCase))
    33	            {
    34	                continue;
    35	            }
    36	
    37	            var path = ResolveManifestPath(root, entry.Path);
    38	            await VerifyHashAsync(path, entry.Sha256, cancellationToken).ConfigureAwait(false);
    39	            var isRules = entry.Path.Equals("RULES.md", StringComparison.OrdinalIgnoreCase);
    40	            var skillName = entry.Path.Split('/', StringSplitOptions.RemoveEmptyEntries)[0];
    41	            artifacts.Add(new ContextArtifact(
    42	                isRules ? ContextArtifactKind.Rules : ContextArtifactKind.Skill,
    43	                isRules
    44	                    ? "governing-rules"
    45	                    : entry.Path.EndsWith("/SKILL.md", StringComparison.OrdinalIgnoreCase)
    46	                        ? skillName
    47	                        : $"{entry.Path}:{skillName}",
    48	                await File.ReadAllTextAsync(path, cancellationToken).ConfigureAwait(false),
    49	                []));
    50	        }
    51	
    52	        artifacts.Add(new ContextArtifact(
    53	            ContextArtifactKind.StopCondition,
    54	            "governance-stop",
    55	            "Stop when proceeding would exceed assigned capabilities, alter scope, or bypass required independent verification.",
    56	            []));
    57	        return artifacts;
    58	    }
