    60	    private static string ResolveRoot(string? configuredRoot)
    61	    {
    62	        var explicitRoot = configuredRoot ?? Environment.GetEnvironmentVariable("AILEDGER_COGNITIVE_ROOT");
    63	        if (!string.IsNullOrWhiteSpace(explicitRoot))
    64	        {
    65	            return Path.GetFullPath(explicitRoot);
    66	        }
    67	
    68	        foreach (var start in new[] { Environment.CurrentDirectory, AppContext.BaseDirectory })
    69	        {
    70	            for (var directory = new DirectoryInfo(start); directory is not null; directory = directory.Parent)
    71	            {
    72	                var candidate = Path.Combine(directory.FullName, "cognitive");
    73	                if (File.Exists(Path.Combine(candidate, "manifest.json")))
    74	                {
    75	                    return candidate;
    76	                }
    77	            }
    78	        }
    79	
    80	        throw new DirectoryNotFoundException(
    81	            "Could not locate the cognitive layer. Use '--cognitive-root PATH' or AILEDGER_COGNITIVE_ROOT.");
    82	    }
