    84	    private static string ResolveManifestPath(string root, string relativePath)
    85	    {
    86	        var path = Path.GetFullPath(Path.Combine(root, relativePath));
    87	        if (!File.Exists(path))
    88	        {
    89	            path = Path.GetFullPath(Path.Combine(root, "skills", relativePath));
    90	        }
    91	
    92	        var relative = Path.GetRelativePath(root, path);
    93	        if (Path.IsPathRooted(relative) || relative.StartsWith("..", StringComparison.Ordinal))
    94	        {
    95	            throw new InvalidDataException($"Cognitive manifest path '{relativePath}' escapes its root.");
    96	        }
    97	
    98	        if (!File.Exists(path))
    99	        {
   100	            throw new FileNotFoundException($"Cognitive artifact '{relativePath}' was not found.", path);
   101	        }
   102	
   103	        return path;
   104	    }
