   106	    private static async Task VerifyHashAsync(
   107	        string path,
   108	        string expectedHash,
   109	        CancellationToken cancellationToken)
   110	    {
   111	        await using var stream = File.OpenRead(path);
   112	        var hash = await SHA256.HashDataAsync(stream, cancellationToken).ConfigureAwait(false);
   113	        var actualHash = Convert.ToHexString(hash);
   114	        if (!string.Equals(actualHash, expectedHash, StringComparison.OrdinalIgnoreCase))
   115	        {
   116	            throw new InvalidDataException($"Cognitive artifact '{path}' does not match its manifest hash.");
   117	        }
   118	    }
