    20	    public static async Task BuildAsync(
    21	        string ledgerRoot,
    22	        string taskId,
    23	        string actorId = "operator",
    24	        string? cognitiveRoot = null)
    25	    {
    26	        var application = new CliApplication(
    27	            TextWriter.Null,
    28	            TextWriter.Null,
    29	            Service,
    30	            _ => throw new InvalidOperationException("Briefing an actor starts no provider."),
    31	            new ContextAssembler());
    32	        // Written to a file rather than to standard output, so a test asserting on what the
    33	        // command under test printed does not also read a manifest.
    34	        var manifestPath = Path.Combine(Path.GetTempPath(), $"brief-{Guid.NewGuid():N}.json");
    35	        var exit = await application.RunAsync(
    36	            ["context", "build", "--root", ledgerRoot, "--task", taskId, "--actor", actorId,
    37	             "--cognitive-root", cognitiveRoot ?? CognitiveRoot(), "--output", manifestPath],
    38	            CancellationToken.None);
